// Picks who gets the lead: active members with an email, paid plans first,
// then (optionally) free listings, keeping the directory's proximity order inside each tier.
const cfg = $('Matching Settings').first().json;
const res = $input.first().json || {};
const raw = res.message;
let members = [];
if (Array.isArray(raw)) members = raw;
else if (raw && typeof raw === 'object') members = Object.values(raw).filter(m => m && typeof m === 'object' && m.user_id);
if (!Number(cfg.sub_id)) members = []; // unknown service: never blast every category

const paid = (cfg.paid_plan_ids || []).map(String);
const tierRank = cfg.tier_rank || {};
const planNames = cfg.plan_names || {};
const seen = new Set();
const eligible = members.filter(m => {
  const id = String(m.user_id);
  const ok = String(m.active) === '2' && /@/.test(String(m.email || '')) && !seen.has(id);
  if (ok) seen.add(id);
  return ok;
});

const ranked = eligible
  .map((m, i) => ({ m, i, rank: Number(tierRank[String(m.subscription_id)] || 0) }))
  .sort((a, b) => b.rank - a.rank || a.i - b.i);

const isPaid = x => paid.includes(String(x.m.subscription_id));
let picked = ranked.filter(isPaid);
if (cfg.fill_with_free) picked = picked.concat(ranked.filter(x => !isPaid(x)));
picked = picked.slice(0, Number(cfg.max_matches) || 3);

const label = m => (m.company || [m.first_name, m.last_name].filter(Boolean).join(' ') || 'Member') +
  ' (#' + m.user_id + ', ' + (planNames[String(m.subscription_id)] || 'plan ' + m.subscription_id) + ')';

const searchOk = res.status === 'success';
return [{ json: {
  search_ok: searchOk,
  search_error: searchOk ? '' : String((res.error && (res.error.message || res.error)) || res.message || 'search failed').slice(0, 300),
  candidates: members.length,
  eligible: eligible.length,
  match_count: picked.length,
  paid_matches: picked.filter(isPaid).length,
  users_to_match: picked.map(x => x.m.user_id).join(','),
  matched_summary: picked.map(x => label(x.m)).join('; ')
} }];

